window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-12faae5442742939"]={"versions": [{"id": "FIG-12faae5442742939", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Dateistruktur- und Inklusionsdiagramm (UML-Paketdiagramm/Komponentendiagramm) für den AUTOSAR LIN-Treiber (BSW-Treiber des Microcontroller Abstraction Layer, MCAL). Es modelliert die C-Quell- und Header-Dateien des Moduls sowie deren statische Abhängigkeiten zu Basis- und Nachbarmodulen (LIN Interface, DET, DEM).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modul besteht aus Implementierungsdateien (<code>Lin.c</code>, <code>Lin_Irq.c</code>, <code>Lin_PBcfg.c</code>) und Header-Dateien (<code>Lin.h</code>, <code>Lin_Cfg.h</code>):</p>\n<ul class=\"fig-list\"><li><code>Lin.h</code> inkludiert <code>Lin_Irq.c</code> und <code>Lin_Cfg.h</code>.\n</li><li><code>Lin.c</code> inkludiert <code>Lin.h</code>, <code>Std_Types.h</code>, <code>LinIf_Cbk.h</code>, <code>Det.h</code> (mit Bedingung: „if development mode is enabled“) und <code>Dem.h</code>.\n</li><li><code>Lin_PBcfg.c</code> inkludiert <code>Lin_Cfg.h</code>.\n</li><li><code>Std_Types.h</code> inkludiert <code>Platform_Types.h</code> und <code>Compiler.h</code>.\n</li><li><code>Dem.h</code> inkludiert <code>Dem_IntErrId.h</code> (Event Id Symbols).\n</li></ul>\n<p class=\"fig-p\">Alle Beziehungen sind als gerichtete <code>includes</code>-Abhängigkeiten (gestrichelte Pfeile) modelliert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Dateiinklusionsdiagramm stellt das Schaubild keine Laufzeitsequenzen oder dynamischen Zustandsübergänge dar. Es definiert die statische Kompilier- und Vorverarbeitungsreihenfolge (Pre-Processor <code>#include</code>-Hierarchie) beim Übersetzungsvorgang des LIN-Treibers.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Dateistruktur für die Implementierung des LIN-Treibers:</p>\n<ul class=\"fig-list\"><li>Trennung von Pre-Compile- (<code>Lin_Cfg.h</code>) und Post-Build-Konfiguration (<code>Lin_PBcfg.c</code>).\n</li><li>Vorgeschriebene Einbindung von Standardtypen (<code>Std_Types.h</code>), Compiler-Abstraktion (<code>Compiler.h</code>) und Plattformtypen (<code>Platform_Types.h</code>).\n</li><li>Bedingte Inklusion des Development Error Tracer (<code>Det.h</code>) nur bei aktiviertem Entwicklungsmodus.\n</li><li>Rückmeldeschnittstelle zu Callbacks des LIN-Interfaces (<code>LinIf_Cbk.h</code>) und Fehlerberichterstattung an das DEM (<code>Dem.h</code>, <code>Dem_IntErrId.h</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-6f9fe944779cb209", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Dateistruktur- und Inklusionsdiagramm (UML-Paketdiagramm/Komponentendiagramm) für den AUTOSAR LIN-Treiber (BSW-Treiber des Microcontroller Abstraction Layer, MCAL). Es modelliert die C-Quell- und Header-Dateien des Moduls sowie deren statische Abhängigkeiten zu Basis- und Nachbarmodulen (LIN Interface, DET, DEM).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modul gliedert sich in Implementierungs- und Konfigurationsdateien sowie Schnittstellen-Header:</p>\n<ul class=\"fig-list\"><li><code>Lin.h</code> inkludiert <code>ComStack_Types.h</code>, <code>Lin_Irq.c</code> und <code>Lin_Cfg.h</code>.\n</li><li><code>Lin.c</code> inkludiert <code>Lin.h</code>, <code>MemMap.h</code>, <code>LinIf_Cbk.h</code>, <code>Det.h</code> und <code>Dem.h</code>.\n</li><li><code>Lin_PBcfg.c</code> inkludiert <code>Lin_Cfg.h</code>.\n</li><li><code>Dem.h</code> inkludiert <code>Dem_IntErrId.h</code>.\n</li></ul>\n<p class=\"fig-p\">Alle Beziehungen sind als durchgezogene gerichtete <code>includes</code>-Pfeile dargestellt. Direkte Inklusionen von <code>Std_Types.h</code>, <code>Platform_Types.h</code> oder <code>Compiler.h</code> sind nicht vorhanden.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Dateiinklusionsdiagramm stellt das Schaubild keine Laufzeitsequenzen oder dynamischen Zustandsübergänge dar. Es definiert die statische Kompilier- und Vorverarbeitungsreihenfolge (Pre-Processor <code>#include</code>-Hierarchie) beim Übersetzungsvorgang des LIN-Treibers.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Inklusionshierarchie für die Software-Architektur des LIN-Treibers:</p>\n<ul class=\"fig-list\"><li><code>Lin.h</code> bezieht plattform- und kommunikationsspezifische Typen über <code>ComStack_Types.h</code>.\n</li><li><code>Lin.c</code> bindet für Speichermapping-Pragmas <code>MemMap.h</code> ein.\n</li><li><code>Det.h</code> ist als Standard-Inklusion ohne Bedingungsvermerk modelliert.\n</li><li>Post-Build-Konfigurationsdaten (<code>Lin_PBcfg.c</code>) hängen ausschließlich von <code>Lin_Cfg.h</code> ab.\n</li><li>Callbacks an das LIN-Interface erfolgen über <code>LinIf_Cbk.h</code>; Diagnoseereignisse werden über <code>Dem.h</code> / <code>Dem_IntErrId.h</code> angebunden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-4eb7a275f61a36a9", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Dateistruktur- und Inklusionsdiagramm (UML-Paketdiagramm/Komponentendiagramm) für den AUTOSAR LIN-Treiber (BSW-Treiber des Microcontroller Abstraction Layer, MCAL). Es modelliert die C-Quell- und Header-Dateien des Moduls sowie deren statische Abhängigkeiten zu Basis- und Nachbarmodulen (LIN Interface, DET, DEM).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modul gliedert sich in Implementierungs- und Konfigurationsdateien sowie Schnittstellen-Header:</p>\n<ul class=\"fig-list\"><li><code>Lin.h</code> inkludiert <code>ComStack_Types.h</code>, <code>Lin_Irq.c</code> und <code>Lin_Cfg.h</code>.\n</li><li><code>Lin.c</code> inkludiert <code>Lin.h</code>, <code>MemMap.h</code>, <code>LinIf_Cbk.h</code>, <code>Det.h</code> und <code>Dem.h</code>.\n</li><li><code>Lin_PBcfg.c</code> inkludiert <code>Lin_Cfg.h</code>.\n</li><li><code>Dem.h</code> inkludiert <code>Dem_IntErrId.h</code>.\n</li></ul>\n<p class=\"fig-p\">Alle Beziehungen sind als durchgezogene gerichtete <code>includes</code>-Pfeile dargestellt. Direkte Inklusionen von <code>Std_Types.h</code>, <code>Platform_Types.h</code> oder <code>Compiler.h</code> sind nicht vorhanden.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Dateiinklusionsdiagramm stellt das Schaubild keine Laufzeitsequenzen oder dynamischen Zustandsübergänge dar. Es definiert die statische Kompilier- und Vorverarbeitungsreihenfolge (Pre-Processor <code>#include</code>-Hierarchie) beim Übersetzungsvorgang des LIN-Treibers.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Inklusionshierarchie für die Software-Architektur des LIN-Treibers:</p>\n<ul class=\"fig-list\"><li><code>Lin.h</code> bezieht plattform- und kommunikationsspezifische Typen über <code>ComStack_Types.h</code>.\n</li><li><code>Lin.c</code> bindet für Speichermapping-Pragmas <code>MemMap.h</code> ein.\n</li><li><code>Det.h</code> ist als Standard-Inklusion ohne Bedingungsvermerk modelliert.\n</li><li>Post-Build-Konfigurationsdaten (<code>Lin_PBcfg.c</code>) hängen ausschließlich von <code>Lin_Cfg.h</code> ab.\n</li><li>Callbacks an das LIN-Interface erfolgen über <code>LinIf_Cbk.h</code>; Diagnoseereignisse werden über <code>Dem.h</code> / <code>Dem_IntErrId.h</code> angebunden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9c69da79acfd69a7", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Dateistruktur- und Inklusionsdiagramm (UML-Paketdiagramm/Komponentendiagramm) für den AUTOSAR LIN-Treiber (BSW-Treiber des Microcontroller Abstraction Layer, MCAL). Es modelliert die C-Quell- und Header-Dateien des Moduls sowie deren statische Abhängigkeiten zu Basis- und Nachbarmodulen (LIN Interface, DET, DEM).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modul gliedert sich in Implementierungs- und Konfigurationsdateien sowie Schnittstellen-Header:</p>\n<ul class=\"fig-list\"><li><code>Lin.h</code> inkludiert <code>ComStack_Types.h</code>, <code>Lin_Irq.c</code> und <code>Lin_Cfg.h</code>.\n</li><li><code>Lin.c</code> inkludiert <code>Lin.h</code>, <code>MemMap.h</code>, <code>LinIf_Cbk.h</code>, <code>Det.h</code> und <code>Dem.h</code>.\n</li><li><code>Lin_PBcfg.c</code> inkludiert <code>Lin_Cfg.h</code>.\n</li><li><code>Dem.h</code> inkludiert <code>Dem_IntErrId.h</code>.\n</li></ul>\n<p class=\"fig-p\">Alle Beziehungen sind als durchgezogene gerichtete <code>includes</code>-Pfeile dargestellt. Direkte Inklusionen von <code>Std_Types.h</code>, <code>Platform_Types.h</code> oder <code>Compiler.h</code> sind nicht vorhanden.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Dateiinklusionsdiagramm stellt das Schaubild keine Laufzeitsequenzen oder dynamischen Zustandsübergänge dar. Es definiert die statische Kompilier- und Vorverarbeitungsreihenfolge (Pre-Processor <code>#include</code>-Hierarchie) beim Übersetzungsvorgang des LIN-Treibers.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Inklusionshierarchie für die Software-Architektur des LIN-Treibers:</p>\n<ul class=\"fig-list\"><li><code>Lin.h</code> bezieht plattform- und kommunikationsspezifische Typen über <code>ComStack_Types.h</code>.\n</li><li><code>Lin.c</code> bindet für Speichermapping-Pragmas <code>MemMap.h</code> ein.\n</li><li><code>Det.h</code> ist als Standard-Inklusion ohne Bedingungsvermerk modelliert.\n</li><li>Post-Build-Konfigurationsdaten (<code>Lin_PBcfg.c</code>) hängen ausschließlich von <code>Lin_Cfg.h</code> ab.\n</li><li>Callbacks an das LIN-Interface erfolgen über <code>LinIf_Cbk.h</code>; Diagnoseereignisse werden über <code>Dem.h</code> / <code>Dem_IntErrId.h</code> angebunden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-12faae5442742939", "to": "FIG-6f9fe944779cb209", "fr": "R2.1.20", "tr": "R3.0.7", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>ComStack_Types.h</code>: Neu aufgenommen als Inklusion über <code>Lin.h</code>.\n</li><li><code>Std_Types.h</code>, <code>Platform_Types.h</code>, <code>Compiler.h</code>: Vollständig aus der Inklusionsstruktur entfernt.\n</li><li><code>MemMap.h</code>: Neu aufgenommen als Inklusion über <code>Lin.c</code>.\n</li><li><code>Det.h</code>: Bedingter Vermerk <code>(if development mode is enabled)</code> entfernt.\n</li><li><code>Dem_IntErrId.h</code>: Zusatz <code>(Event Id Symbols)</code> entfernt.\n</li><li>Verbindungsstile von gestrichelten Linien mit offenen Pfeilspitzen auf durchgezogene Pfeile umgestellt.\n</li></ul>"}, {"from": "FIG-6f9fe944779cb209", "to": "FIG-4eb7a275f61a36a9", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-4eb7a275f61a36a9", "to": "FIG-9c69da79acfd69a7", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>Dem_IntErrId.h</code>: Box am unteren Bildrand durch Beschnitt der Grafik unten teilweise abgeschnitten.\n</li></ul>"}]};
